def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    from collections import Counter
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx))
                        stack.append((yy,xx))
            r0 = min(y for y,x in cells); r1 = max(y for y,x in cells)
            c0 = min(x for y,x in cells); c1 = max(x for y,x in cells)
            if r1-r0 < 2 or c1-c0 < 2:
                continue
            perimeter = all(grid[r0][x] == color and grid[r1][x] == color for x in range(c0,c1+1)) and all(grid[y][c0] == color and grid[y][c1] == color for y in range(r0,r1+1))
            if not perimeter:
                continue
            inside = [grid[y][x] for y in range(r0+1,r1) for x in range(c0+1,c1)]
            if not inside or any(v != inside[0] for v in inside):
                continue
            fill = 2 if len(inside) % 2 == 0 else 7
            for y in range(r0+1,r1):
                for x in range(c0+1,c1):
                    out[y][x] = fill
    return out
